import React from 'react';
import { DigoAsset } from '@digo-org/digo-api';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip } from 'recharts';

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  render() {
    const backgroundColor = this.globalParameters['background-color'] as string;
    const showLabels = this.globalParameters['show-labels'] as boolean;
    const showLegend = this.globalParameters['show-legend'] as boolean;
    const showTooltip = this.globalParameters['show-tooltip'] as boolean;
    const innerRadius = this.globalParameters['inner-radius'] as number;
    const outerRadius = this.globalParameters['outer-radius'] as number;
    const paddingAngle = this.globalParameters['padding-angle'] as number;
    const startAngle = this.globalParameters['start-angle'] as number;
    const endAngle = this.globalParameters['end-angle'] as number;
    const labelPosition = this.globalParameters['label-position'] as string;

    const data = this.instances?.map((instance, index) => ({
      ...instance,
      name: instance['slice-label'] as string,
      value: instance['slice-value'] as number
    })) || [];

    const renderLabel = (entry: any) => {
      if (!showLabels) return null;
      return entry.name;
    };

    return (
      <div 
        className="w-full h-full flex items-center justify-center"
        style={{ backgroundColor }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={data}
              cx="50%"
              cy="50%"
              labelLine={labelPosition === 'outside'}
              label={showLabels ? renderLabel : false}
              outerRadius={outerRadius}
              innerRadius={innerRadius}
              paddingAngle={paddingAngle}
              startAngle={startAngle}
              endAngle={endAngle}
              dataKey="value"
            >
              {data.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            {showTooltip && <Tooltip />}
            {showLegend && <Legend />}
          </PieChart>
        </ResponsiveContainer>
      </div>
    );
  }
}

